from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/movie')
def show_movie():
    movie_name = request.args.get('name')
    genre = request.args.get('genre')
    rating = request.args.float('rating')

    if rating < 5:
        return '<h2>{}</h2><p>{}</p>".format(movie_name, genre)

    return f'<h2>{movie_name}</h2><p>Rating: {rating}</p>'

if __name__ == '__main__':
    app.run()

