from ansible bit.pyres import cache

def purge_old_bit_pyres():
    cache.path = '/data/bit/pyres'
    retention_period = -1 # Keep no old bits
    payloads = []
    for pid, bits in cache._store.items():
        if len(bits) > retention_period:
            continue
        payloads.append(pid)
    cache._store = {k: v for k, v in cache._store.items() if k not in payloads}

    for pid in payloads:
        bits = cache._store[pid]
        for bit in bits:
            bit.delete()

purge_old_bit_pyres()

