from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/status', methods=['POST'])
def status():
    interaction_id = request.form['interaction_id']

    status_map = {
        'new_status': 'New status requested',
        'terminated': 'Interaction terminated',
        'error': 'Error occurred'
    }

    status = status_map.get(interaction_id, 'Unknown status')

    response = jsonify({'status': status})
    return response
